1	import React, { useEffect, useMemo, useState } from 'react';
2	import { useLocation, useNavigate } from 'react-router-dom';
3	import axios from 'axios';
4	import VisibilityIcon from '@mui/icons-material/Visibility';
5	import BlockIcon from '@mui/icons-material/Block';
6	import CheckCircleIcon from '@mui/icons-material/CheckCircle';
7	import CancelIcon from '@mui/icons-material/Cancel';
8	import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
9	import Sidebar from '../components/Sidebar';
10	import SafeMuiIcon from '../components/SafeMuiIcon';
11	import PasswordInput from '../components/PasswordInput';
12	import '../css/Dashboard.css';
13	import '../css/Users.css';
14	import { API_BASE_URL } from '../constants/api';
15	
16	// Compact badge + separate readable description — never one long combined label.
17	const ROLE_META = {
18	  FM: { badge: 'FM', description: 'Facilities Manager' },
19	  Tenant: { badge: 'Tenant', description: 'Unit Owner' },
20	  Staff: { badge: 'Staff', description: 'Worker' }
21	};
22	
23	const emptyFilters = {
24	  query: '',
25	  role: 'All',
26	  status: 'All',
27	  faceId: 'All'
28	};
29	
30	const Users = () => {
31	  const navigate = useNavigate();
32	  const location = useLocation();
33	  const [users, setUsers] = useState([]);
34	  const [loading, setLoading] = useState(true);
35	  const [modal, setModal] = useState({ isOpen: false, user: null, action: null });
36	  const [confirmText, setConfirmText] = useState('');
37	  const [modalError, setModalError] = useState('');
38	  const [notification, setNotification] = useState(location.state?.notice || '');
39	  const [filters, setFilters] = useState(emptyFilters);
40	
41	  const token = localStorage.getItem('accessToken');
42	  const currentUserId = localStorage.getItem('userId');
43	  const role = localStorage.getItem('userRole');
44	
45	  const [addOpen, setAddOpen] = useState(false);
46	  const [newUser, setNewUser] = useState({ name: '', email: '', password: '' });
47	  const [addSubmitting, setAddSubmitting] = useState(false);
48	  const [addError, setAddError] = useState('');
49	
50	  const fetchUsers = async () => {
51	    setLoading(true);
52	    try {
53	      const response = await axios.get(`${API_BASE_URL}/user`, {
54	        headers: { Authorization: `Bearer ${token}` }
55	      });
56	      setUsers(Array.isArray(response.data) ? response.data : []);
57	    } catch (error) {
58	      console.error('Database sync failed:', error);
59	      setUsers([]);
60	    } finally {
61	      setLoading(false);
62	    }
63	  };
64	
65	  useEffect(() => {
66	    fetchUsers();
67	  }, []);
68	
69	  useEffect(() => {
70	    if (!notification) return undefined;
71	    const timer = setTimeout(() => setNotification(''), 4000);
72	    return () => clearTimeout(timer);
73	  }, [notification]);
74	
75	  const summary = useMemo(() => ({
76	    total: users.length,
77	    active: users.filter((u) => u.isActive !== false).length,
78	    suspended: users.filter((u) => u.isActive === false).length,
79	    enrolled: users.filter((u) => Boolean(u.isEnrolled)).length
80	  }), [users]);
81	
82	  const filteredUsers = useMemo(() => users.filter((user) => {
83	    const query = filters.query.trim().toLowerCase();
84	    const matchesQuery = !query
85	      || user.name?.toLowerCase().includes(query)
86	      || user.email?.toLowerCase().includes(query);
87	    const matchesRole = filters.role === 'All' || user.role === filters.role;
88	    const matchesStatus = filters.status === 'All'
89	      || (filters.status === 'Active' ? user.isActive !== false : user.isActive === false);
90	    const matchesFaceId = filters.faceId === 'All'
91	      || (filters.faceId === 'Enrolled' ? Boolean(user.isEnrolled) : !user.isEnrolled);
92	    return matchesQuery && matchesRole && matchesStatus && matchesFaceId;
93	  }), [users, filters]);
94	
95	  const onNewField = (e) => setNewUser((prev) => ({ ...prev, [e.target.name]: e.target.value }));
96	  const onFilterChange = (e) => setFilters((prev) => ({ ...prev, [e.target.name]: e.target.value }));
97	
98	  const openAdd = () => {
99	    setAddError('');
100	    setNewUser({ name: '', email: '', password: '' });
101	    setAddOpen(true);
102	  };
103	  const closeAdd = () => setAddOpen(false);
104	
105	  const createTenant = async (e) => {
106	    e.preventDefault();
107	    setAddSubmitting(true);
108	    setAddError('');
109	    try {
110	      await axios.post(`${API_BASE_URL}/user/manual-create`, newUser, { headers: { Authorization: `Bearer ${token}` } });
111	      setAddOpen(false);
112	      setNotification(`Tenant account created for ${newUser.name}.`);
113	      fetchUsers();
114	    } catch (err) {
115	      setAddError(err.response?.data?.errors?.[0] || err.response?.data?.message || 'Failed to create account.');
116	    } finally {
117	      setAddSubmitting(false);
118	    }
119	  };
120	
121	  const openModal = (user, action = 'suspend') => {
122	    setConfirmText('');
123	    setModalError('');
124	    setModal({ isOpen: true, user, action });
125	  };
126	
127	  const closeModal = () => {
128	    setModal({ isOpen: false, user: null, action: null });
129	    setConfirmText('');
130	    setModalError('');
131	  };
132	
133	  const handleConfirmAction = async () => {
134	    const { id, isActive, name } = modal.user;
135	    setModalError('');
136	
137	    if (modal.action === 'delete' && confirmText !== name) {
138	      setModalError(`Type ${name} to confirm permanent off-boarding.`);
139	      return;
140	    }
141	
142	    try {
143	      if (modal.action === 'delete') {
144	        await axios.delete(`${API_BASE_URL}/user/${id}`, {
145	          headers: { Authorization: `Bearer ${token}` }
146	        });
147	        await fetchUsers();
148	        setNotification(`${name} was permanently removed from FlowGuard.`);
149	        closeModal();
150	        return;
151	      }
152	
153	      await axios.put(`${API_BASE_URL}/user/suspend/${id}`, {}, {
154	        headers: { Authorization: `Bearer ${token}` }
155	      });
156	      setUsers((prevUsers) => prevUsers.map((u) => (u.id === id ? { ...u, isActive: !isActive } : u)));
157	      closeModal();
158	    } catch (error) {
159	      setModalError(error.response?.data?.message || error.response?.data?.error || `Failed to ${modal.action === 'delete' ? 'remove' : 'update access for'} ${name}.`);
160	      console.error(error);
161	    }
162	  };
163	
164	  const renderRoleBadge = (userRole) => {
165	    const meta = ROLE_META[userRole] || { badge: String(userRole), description: '' };
166	    return (
167	      <div className="role-cell">
168	        <span className={`role-badge role-${String(userRole).toLowerCase()}`}>{meta.badge}</span>
169	        {meta.description && <span className="role-description">{meta.description}</span>}
170	      </div>
171	    );
172	  };
173	
174	  const renderStatusBadge = (user) => (
175	    <span className={`account-status-badge ${user.isActive === false ? 'suspended' : 'active'}`} role="status">
176	      {user.isActive === false ? 'Suspended' : 'Active'}
177	    </span>
178	  );
179	
180	  return (
181	    <div className="dashboard-layout">
182	      <Sidebar />
183	
184	      <main className="dashboard-main">
185	        {modal.isOpen && (
186	          <div className="modal-overlay">
187	            <div className={`modal-content security-modal ${modal.action === 'delete' ? 'delete-variant' : ''}`}>
188	              <div className="modal-header">
189	                <span className="modal-icon">{modal.action === 'delete' ? '!' : modal.user.isActive ? '!' : '+'}</span>
190	                <h3>{modal.action === 'delete' ? 'Permanent Off-boarding' : 'Security Confirmation'}</h3>
191	              </div>
192	              {modal.action === 'delete' ? (
193	                <>
194	                  <p>
195	                    Permanently remove login access, Face ID enrolment and operational access for this user (<strong>{modal.user.name}</strong>)?
196	                  </p>
197	                  <p className="delete-warning-copy">
198	                    Attendance records will be deleted, linked security logs will remain anonymised, and operational bookings will be safely unlinked where applicable.
199	                  </p>
200	                  <label className="confirm-name-field">
201	                    Type the user's full name to confirm
202	                    <input value={confirmText} onChange={(e) => setConfirmText(e.target.value)} placeholder={modal.user.name} />
203	                  </label>
204	                </>
205	              ) : (
206	                <p>
207	                  Are you sure you want to <strong>{modal.user.isActive ? 'Suspend' : 'Reactivate'}</strong> access for <strong>{modal.user.name}</strong>?
208	                </p>
209	              )}
210	              {modalError && <div className="modal-error" role="alert">{modalError}</div>}
211	              <div className="modal-actions">
212	                <button className="cancel-btn" onClick={closeModal}>Cancel</button>
213	                <button
214	                  className={`confirm-btn ${modal.action === 'delete' ? 'delete-btn' : modal.user.isActive ? 'suspend-btn' : 'reactivate-btn'}`}
215	                  onClick={handleConfirmAction}
216	                  disabled={modal.action === 'delete' && confirmText !== modal.user.name}
217	                >
218	                  {modal.action === 'delete' ? 'Permanently Delete' : `Confirm ${modal.user.isActive ? 'Suspension' : 'Reactivation'}`}
219	                </button>
220	              </div>
221	            </div>
222	          </div>
223	        )}
224	
225	        {addOpen && (
226	          <div className="modal-overlay" onClick={closeAdd}>
227	            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
228	              <div className="modal-header">
229	                <span className="modal-icon">+</span>
230	                <h3>Add Tenant Account</h3>
231	              </div>
232	              {addError && <div className="add-user-error">{addError}</div>}
233	              <form className="add-user-form" onSubmit={createTenant}>
234	                <div>
235	                  <label>Full Name</label>
236	                  <input name="name" value={newUser.name} onChange={onNewField} placeholder="e.g., Jane Tan" required />
237	                </div>
238	                <div>
239	                  <label>Email</label>
240	                  <input name="email" type="email" value={newUser.email} onChange={onNewField} placeholder="name@company.com" required />
241	                </div>
242	                <div>
243	                  <label>Temporary Password</label>
244	                  <PasswordInput variant="dark" name="password" value={newUser.password} onChange={onNewField} placeholder="min 8 characters" required />
245	                </div>
246	                <div className="modal-actions">
247	                  <button type="button" className="cancel-btn" onClick={closeAdd}>Cancel</button>
248	                  <button type="submit" className="add-user-btn" disabled={addSubmitting}>
249	                    {addSubmitting ? 'Creating...' : 'Create Tenant'}
250	                  </button>
251	                </div>
252	              </form>
253	            </div>
254	          </div>
255	        )}
256	
257	        {notification && <div className="users-toast">{notification}</div>}
258	
259	        <div className="users-container">
260	          <header className="dashboard-header users-header">
261	            <div className="header-titles">
262	              <h1>User Management</h1>
263	              <p>Manage user accounts, roles, Face ID enrolment and access status.</p>
264	            </div>
265	            {role === 'FM' && <button className="add-user-btn" onClick={openAdd}>+ Add Tenant</button>}
266	          </header>
267	
268	          <section className="user-summary-grid" aria-label="User summary">
269	            <div><span>Total Users</span><strong>{summary.total}</strong></div>
270	            <div><span>Active</span><strong>{summary.active}</strong></div>
271	            <div><span>Suspended</span><strong>{summary.suspended}</strong></div>
272	            <div><span>Face ID Enrolled</span><strong>{summary.enrolled}</strong></div>
273	          </section>
274	
275	          <section className="user-filter-bar" aria-label="User filters">
276	            <input name="query" value={filters.query} onChange={onFilterChange} placeholder="Search name or email" aria-label="Search by name or email" />
277	            <select name="role" value={filters.role} onChange={onFilterChange} aria-label="Filter by role">
278	              <option>All</option><option>FM</option><option>Tenant</option><option>Staff</option>
279	            </select>
280	            <select name="status" value={filters.status} onChange={onFilterChange} aria-label="Filter by status">
281	              <option>All</option><option>Active</option><option>Suspended</option>
282	            </select>
283	            <select name="faceId" value={filters.faceId} onChange={onFilterChange} aria-label="Filter by Face ID">
284	              <option>All</option><option>Enrolled</option><option>Not Enrolled</option>
285	            </select>
286	          </section>
287	
288	          <div className="table-wrapper">
289	            {loading ? (
290	              <p style={{ padding: '40px', color: '#94a3b8', textAlign: 'center' }}>Syncing with FlowGuard Database...</p>
291	            ) : (
292	              <table className="users-table">
293	                <thead>
294	                  <tr>
295	                    <th>Personnel</th>
296	                    <th>Role</th>
297	                    <th>Email</th>
298	                    <th>Status</th>
299	                    <th>Face ID</th>
300	                    <th>Joined</th>
301	                    <th>Actions</th>
302	                  </tr>
303	                </thead>
304	                <tbody>
305	                  {filteredUsers.length === 0 ? (
306	                    <tr><td colSpan="7" style={{ textAlign: 'center', padding: '40px', color: '#64748b' }}>No users match the current filters.</td></tr>
307	                  ) : filteredUsers.map((u) => {
308	                    const isSelf = String(u.id) === String(currentUserId);
309	                    return (
310	                      <tr key={u.id} className={u.isActive === false ? 'row-suspended' : ''}>
311	                        <td className="user-name-cell" data-label="Personnel">
312	                          <div className="user-identity">
313	                            <div className="user-avatar-small">{u.name?.charAt(0).toUpperCase()}</div>
314	                            <span className="user-name-text">
315	                              <span className="user-name-value">{u.name}</span>
316	                              {isSelf && <span className="self-tag">(You)</span>}
317	                            </span>
318	                          </div>
319	                        </td>
320	                        <td data-label="Role">{renderRoleBadge(u.role)}</td>
321	                        <td className="access-cell email-cell" data-label="Email" title={u.email}>{u.email}</td>
322	                        <td data-label="Status">{renderStatusBadge(u)}</td>
323	                        <td data-label="Face ID">
324	                          <span className={`presence-tag ${u.isEnrolled ? 'on-site' : 'off-site'}`} title={u.isEnrolled ? 'A protected biometric template is enrolled' : 'No Face ID enrolled yet'}>
325	                            {u.isEnrolled ? <><SafeMuiIcon icon={CheckCircleIcon} fontSize="small" aria-hidden="true" /> Enrolled</> : <><SafeMuiIcon icon={CancelIcon} fontSize="small" aria-hidden="true" /> Not Enrolled</>}
326	                          </span>
327	                        </td>
328	                        <td className="time-cell" data-label="Joined">{new Date(u.createdAt).toLocaleDateString('en-SG')}</td>
329	                        <td className="actions-cell" data-label="Actions">
330	                          {/* Face ID enrol/re-enrol intentionally lives in the
331	                              enrolment flow (first-time) and Settings (self
332	                              re-enrolment) — never as a row action here. */}
333	                          <div className="action-button-group" aria-label={`Actions for ${u.name}`}>
334	                            <button className="action-btn action-neutral" onClick={() => navigate(`/user-logs/${u.id}`)}>
335	                              <SafeMuiIcon icon={VisibilityIcon} fontSize="inherit" aria-hidden="true" />
336	                              View Logs
337	                            </button>
338	                            <button className={`action-btn ${u.isActive === false ? 'action-restore' : 'action-warning'} ${isSelf ? 'disabled-action' : ''}`} onClick={() => !isSelf && openModal(u, 'suspend')} disabled={isSelf}>
339	                              <SafeMuiIcon icon={u.isActive === false ? CheckCircleIcon : BlockIcon} fontSize="inherit" aria-hidden="true" />
340	                              {u.isActive === false ? 'Reactivate' : 'Suspend'}
341	                            </button>
342	                            <button className={`action-btn action-danger ${isSelf ? 'disabled-action' : ''}`} onClick={() => !isSelf && openModal(u, 'delete')} disabled={isSelf}>
343	                              <SafeMuiIcon icon={DeleteOutlineIcon} fontSize="inherit" aria-hidden="true" />
344	                              Delete
345	                            </button>
346	                          </div>
347	                        </td>
348	                      </tr>
349	                    );
350	                  })}
351	                </tbody>
352	              </table>
353	            )}
354	          </div>
355	        </div>
356	      </main>
357	    </div>
358	  );
359	};
360	
361	export default Users;
