+  flex: 1 1 auto;
+  display: flex;
+  flex-direction: column;
+  justify-content: flex-end;
+  align-items: stretch;
+}
+
+.trend-bar {
+  width: 100%;
+  border-radius: 3px 3px 0 0;
+  min-height: 0;
+}
+
+/* Critical sits on top of High in the stack; each keeps a hairline when non-zero. */
+.trend-bar-critical { background: #ef4444; }
+.trend-bar-high { background: #f59e0b; border-radius: 0; }
+.trend-day .trend-bar-high:last-child { border-radius: 3px 3px 0 0; }
+
+.trend-label {
+  font-size: 0.72rem;
