+  -webkit-box-orient: vertical;
+  word-break: break-word;
+}
+
+.zone-bar-track {
+  background: #0b0f1a;
+  border-radius: 999px;
+  height: 12px;
+  overflow: hidden;
+}
+
+.zone-bar {
+  display: block;
+  height: 100%;
+  min-width: 4px;
+  border-radius: 999px;
+  background: linear-gradient(to right, #3b82f6, #60a5fa);
+}
+
+.zone-count {
+  font-size: 0.9rem;
+  font-weight: 700;
+  color: #f8fafc;
+  min-width: 1.5ch;
+  text-align: right;
+}
+
+/* Screen-reader-only helper (mirrors chart data as a table for assistive tech). */
+.sr-only {
+  position: absolute;
