toolUseResult.newString:
/* =========================================
   TABLET & MOBILE — responsive user cards (<= 1024px)
   Each table row becomes a self-contained card with visible field labels
   (from each cell's data-label) and a two-column metadata grid.
   ========================================= */
@media (max-width: 1024px) {
    /* Summary: two columns on tablet. Search takes the full width; the three
       selects wrap onto the row below it. */
    .user-summary-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .user-filter-bar {
        grid-template-columns: 1fr 1fr;
    }

    .user-filter-bar input[name="query"] {
        grid-column: 1 / -1;
    }

    /* The wrapper is no longer the card — each row is. */
    .table-wrapper {
        background: transparent;
        border: none;
        box-shadow: none;
        overflow-x: visible;
    }

    .users-table,
    .users-table tbody {
        display: block;
        width: 100%;
    }

    .users-table thead { display: none; }

    .users-table tbody tr {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 12px 16px;
        margin-bottom: 16px;
        padding: 16px;
        border: 1px solid #334155;
        border-radius: 12px;
        background: #1e293b;
    }

    .users-table td {
        display: flex;
        flex-direction: column;
        gap: 4px;
        padding: 0;
        border: none;
        min-width: 0;
        font-size: 0.9rem;
        white-space: normal;
    }

    /* Visible field label from the cell's data-label. */
    .users-table td::before {
        content: attr(data-label);
        font-size: 0.68rem;
        font-weight: 800;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: #94a3b8;
    }

    /* Card ordering: name (full) / role | status / email (full) /
       face id | joined / actions (full). Uses order so DOM sequence
       (Role, Email, Status, ...) still reads cleanly two-up. */
    .users-table td.user-name-cell { order: 1; grid-column: 1 / -1; }
    .users-table td[data-label="Role"] { order: 2; }
    .users-table td[data-label="Status"] { order: 3; }
    .users-table td.email-cell { order: 4; grid-column: 1 / -1; }
    .users-table td[data-label="Face ID"] { order: 5; }
    .users-table td.time-cell { order: 6; }
    .users-table td.actions-cell { order: 7; grid-column: 1 / -1; }

    /* Personnel is the card title and Actions speak for themselves — no label. */
    .users-table td.user-name-cell::before,
    .users-table td.actions-cell::before {
        display: none;
    }

    .users-table td.user-name-cell {
        padding-bottom: 12px;
        border-bottom: 1px solid #334155;
        font-size: 1rem;
    }

    .user-identity { justify-content: flex-start; }
    .email-cell { overflow-wrap: anywhere; }

    /* Compact action group: View Logs | Suspend, with the destructive Delete
       separated onto its own full-width row below. */
    .action-button-group {
        display: grid;
        grid-template-columns: 1fr 1fr;
        align-items: stretch;
        gap: 10px;
        width: 100%;
    }

    .action-btn {
        width: auto;
        min-height: 44px;
        font-size: 0.8rem;
    }

    .action-btn.action-danger {
        grid-column: 1 / -1;
        margin-top: 2px;
    }
}

/* =========================================
   PHONE — single-column user card (<= 520px, covers 390px & 430px)
   ========================================= */
@media (max-width: 520px) {
    .user-summary-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .user-filter-bar {
        grid-template-columns: 1fr;
    }

    .user-filter-bar input[name="query"] {
        grid-column: auto;
    }

    /* One label/value row per field. Action buttons stay a readable 2-col grid. */
    .users-table tbody tr {
        grid-template-columns: 1fr;
    }
}

