// Frontend tests — User Management retains every important field/action across
// layouts, and each metadata cell carries the data-label the responsive card CSS
// renders as a visible field label (::before content: attr(data-label)).
import React from 'react';
import { render, waitFor } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { vi, describe, test, expect, beforeEach } from 'vitest';

const { mockGet } = vi.hoisted(() => ({ mockGet: vi.fn() }));
vi.mock('axios', () => ({
  default: {
    get: mockGet,
    post: vi.fn(),
    put: vi.fn(),
    delete: vi.fn(),
  },
}));

import Users from '../../src/pages/Users';

const SAMPLE_USERS = [
  {
    id: 1,
    name: 'Jane Tan',
    // Deliberately long address to exercise overflow-wrap: anywhere.
    email: 'jane.a.very.long.email.address@subdomain.company.example.com',
    role: 'Tenant',
    isActive: true,
    isEnrolled: true,
    createdAt: '2026-01-15T00:00:00Z',
  },
  {
    id: 2,
    name: 'Bob Lee',
    email: 'bob@co.com',
    role: 'Staff',
    isActive: false,
    isEnrolled: false,
    createdAt: '2026-02-20T00:00:00Z',
  },
];

const renderUsers = () => render(<MemoryRouter><Users /></MemoryRouter>);

beforeEach(() => {
  localStorage.clear();
  localStorage.setItem('userRole', 'FM');
  localStorage.setItem('userId', '999');
  localStorage.setItem('userName', 'Flow Manager');
  localStorage.setItem('accessToken', 'test-token');
  mockGet.mockReset();
  mockGet.mockResolvedValue({ data: SAMPLE_USERS });
});

describe('User Management — fields and actions preserved', () => {
  test('renders every column header for the desktop table', async () => {
    renderUsers();
    await waitFor(() => expect(document.querySelector('.users-table')).toBeTruthy());
    const headers = Array.from(document.querySelectorAll('.users-table thead th'))
      .map((th) => th.textContent.trim());
    ['Personnel', 'Role', 'Email', 'Status', 'Face ID', 'Joined', 'Actions']
      .forEach((label) => expect(headers).toContain(label));
  });

  test('every metadata cell carries a data-label (the mobile field label source)', async () => {
    renderUsers();
    await waitFor(() => expect(document.querySelector('.users-table tbody tr')).toBeTruthy());
    const firstRow = document.querySelector('.users-table tbody tr');
    ['Personnel', 'Role', 'Email', 'Status', 'Face ID', 'Joined', 'Actions']
      .forEach((label) => {
        expect(firstRow.querySelector(`td[data-label="${label}"]`)).toBeTruthy();
      });
  });

  test('shows role, email, status, Face ID state and joined date values', async () => {
    renderUsers();
    await waitFor(() => expect(document.querySelector('.users-table tbody tr')).toBeTruthy());

    // Personnel + email
    expect(document.body.textContent).toContain('Jane Tan');
    expect(document.querySelector('.email-cell').textContent)
      .toContain('jane.a.very.long.email.address@subdomain.company.example.com');
    // Role badge + Face ID state + status for both users
    expect(document.body.textContent).toContain('Enrolled');
    expect(document.body.textContent).toContain('Not Enrolled');
    expect(document.body.textContent).toContain('Active');
    expect(document.body.textContent).toContain('Suspended');
  });

  test('every row keeps View Logs, Suspend/Reactivate and Delete actions', async () => {
    renderUsers();
    await waitFor(() => expect(document.querySelectorAll('.users-table tbody tr').length).toBe(2));

    const rows = document.querySelectorAll('.users-table tbody tr');
    rows.forEach((row) => {
      const actionText = row.querySelector('.action-button-group').textContent;
      expect(actionText).toContain('View Logs');
      expect(actionText).toContain('Delete');
    });
    // Active user can be Suspended; suspended user can be Reactivated.
    expect(rows[0].textContent).toContain('Suspend');
    expect(rows[1].textContent).toContain('Reactivate');
    // Destructive action is a distinct, separately-styled control.
    expect(rows[0].querySelector('.action-btn.action-danger')).toBeTruthy();
  });

  test('summary and filter controls render (search + role/status/faceId filters)', async () => {
    renderUsers();
    await waitFor(() => expect(document.querySelector('.user-summary-grid')).toBeTruthy());
    expect(document.querySelector('.user-filter-bar input[name="query"]')).toBeTruthy();
    expect(document.querySelector('.user-filter-bar select[name="role"]')).toBeTruthy();
    expect(document.querySelector('.user-filter-bar select[name="status"]')).toBeTruthy();
    expect(document.querySelector('.user-filter-bar select[name="faceId"]')).toBeTruthy();
    expect(document.querySelectorAll('.user-summary-grid > div').length).toBe(4);
  });
});

