/* =========================================
   RESPONSIVE USER CARDS — dedicated markup (.user-card-list).
   Rendered from the same filteredUsers as the table and shown <= 1024px in
   place of it. This is a purpose-built card DOM, NOT a CSS table-to-card
   conversion, so no table-layout/percentage-column/min-width sizing leaks in
   and there is no per-character wrapping.
   ========================================= */
.user-card-list {
    display: none; /* desktop/laptop use the table */
    list-style: none;
    margin: 0;
    padding: 0;
}

.users-loading-state,
.users-empty-state {
    padding: 40px;
    text-align: center;
    color: #94a3b8;
}

@media (max-width: 1024px) {
    /* Summary: two columns on tablet. Search spans the row; selects sit below. */
    .user-summary-grid { grid-template-columns: repeat(2, 1fr); }
    .user-filter-bar { grid-template-columns: 1fr 1fr; }
    .user-filter-bar input[name="query"] { grid-column: 1 / -1; }

    /* Swap representations: hide the table, show the cards. */
    .users-desktop-table { display: none; }

    .user-card-list {
        display: grid;
        grid-template-columns: 1fr;
        gap: 16px;
    }

    .user-card {
        width: 100%;
        min-width: 0;
        box-sizing: border-box;
        background: #1e293b;
        border: 1px solid #334155;
        border-radius: 12px;
        padding: 18px;
        display: flex;
        flex-direction: column;
        gap: 16px;
    }

    .user-card-suspended { opacity: 0.7; }

    /* --- Header: avatar + name + role/status badges --- */
    .user-card-head {
        display: flex;
        align-items: center;
        gap: 12px;
        min-width: 0;
    }

    .user-card-identity {
        min-width: 0;
        display: flex;
        flex-direction: column;
        gap: 6px;
    }

    .user-card-name {
        font-size: 1.05rem;
        font-weight: 700;
        color: #f8fafc;
