        grid-column: 1 / -1;
    }

    /* The wrapper is no longer the card — each row is. */
    .table-wrapper {
        background: transparent;
        border: none;
        box-shadow: none;
        overflow-x: visible;
    }

    .users-table,
    .users-table tbody {
        display: block;
        width: 100%;
    }

