// Frontend tests — manual add-user controls (role-gated) on User Management & My Staff.
import React from "react";
import fs from "node:fs";
import path from "node:path";
import { render, screen, fireEvent, within } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { vi, describe, test, expect, beforeEach } from "vitest";

const { mockGet, mockPost } = vi.hoisted(() => ({
  mockGet: vi.fn((url) => {
    if (url === "/user/my-code") {
      return Promise.resolve({ data: { companyCode: "FLOW-TEST", codeCurrentUsage: 0, codeMaxUsage: 10 } });
    }
    return Promise.resolve({ data: [] });
  }),
  mockPost: vi.fn(() => Promise.resolve({ data: {} })),
}));
vi.mock("axios", () => ({ default: { get: mockGet, post: mockPost } }));

import Users from "../../src/pages/Users";
import StaffManagement from "../../src/pages/StaffManagement";

const renderUsers = () => render(<MemoryRouter><Users /></MemoryRouter>);
const renderStaff = () => render(<MemoryRouter><StaffManagement /></MemoryRouter>);

beforeEach(() => {
  vi.clearAllMocks();
  localStorage.clear();
  localStorage.setItem("accessToken", "test-token");
});

describe("User Management — Add Tenant (FM)", () => {
  test("FM sees the + Add Tenant button", () => {
    localStorage.setItem("userRole", "FM");
    renderUsers();
    expect(screen.getByRole("button", { name: /Add Tenant/i })).toBeTruthy();
  });

  test("User Management does NOT show Re-enroll My Face ID (moved to Settings)", () => {
    localStorage.setItem("userRole", "FM");
    renderUsers();
    expect(screen.queryByText(/Re-enroll My Face ID/i)).toBeNull();
  });

  test("FM does NOT see an 'Add FM' control (FM accounts are seed/setup only)", () => {
    localStorage.setItem("userRole", "FM");
    renderUsers();
    expect(screen.queryByRole("button", { name: /Add FM/i })).toBeNull();
    expect(screen.getByRole("button", { name: /Add Tenant/i })).toBeTruthy();
  });

  test("a user row offers ONLY View Logs, Suspend/Reactivate and Delete (no Face ID row action)", async () => {
    localStorage.setItem("userRole", "FM");
    mockGet.mockResolvedValueOnce({
      data: [{ id: 5, name: "Jane Tan", email: "jane@x.com", role: "Tenant", isActive: true, isEnrolled: false, createdAt: new Date().toISOString(), locationStatus: "Off-Site" }],
    });
    const { container } = renderUsers();
    // Name now appears in both the desktop table and the responsive card list —
    // scope the row-action assertions to the desktop table representation.
    await screen.findAllByText("Jane Tan");
    const table = within(container.querySelector(".users-table"));
    expect(table.getByRole("button", { name: /View Logs/i })).toBeTruthy();
    expect(table.getByRole("button", { name: /Suspend/i })).toBeTruthy();
    expect(table.getByRole("button", { name: /Delete/i })).toBeTruthy();
    // Face ID enrolment stays in the enrolment flow / Settings, not here.
    expect(table.queryByRole("button", { name: /Face ID/i })).toBeNull();
    const rowActions = table.getByLabelText("Actions for Jane Tan");
    expect(rowActions.querySelectorAll("button").length).toBe(3);
  });

  test("non-FM does not see the + Add Tenant button", () => {
    localStorage.setItem("userRole", "Tenant");
    renderUsers();
    expect(screen.queryByRole("button", { name: /Add Tenant/i })).toBeNull();
  });

  test("clicking + Add Tenant opens the modal", async () => {
    localStorage.setItem("userRole", "FM");
    renderUsers();
    fireEvent.click(screen.getByRole("button", { name: /Add Tenant/i }));
    expect(await screen.findByText(/Add Tenant Account/i)).toBeTruthy();
  });
});

describe("User Management — table layout", () => {
  const USERS = [
    { id: 5, name: "Tan Xiu Li, Felicia", email: "felicia@flowguard.dev", role: "FM", isActive: true, isEnrolled: true, createdAt: "2026-01-05T08:00:00+08:00" },
    { id: 6, name: "Jane Tan", email: "jane.tan@very-long-company-domain.example.com", role: "Tenant", isActive: true, isEnrolled: false, createdAt: "2026-02-10T08:00:00+08:00" },
  ];

  beforeEach(() => {
    localStorage.setItem("userRole", "FM");
    localStorage.setItem("userId", "5");
    mockGet.mockResolvedValueOnce({ data: USERS });
  });

  test("'(You)' renders as ONE inline badge beside the name — it cannot split apart", async () => {
    const { container } = renderUsers();
    await screen.findAllByText("Tan Xiu Li, Felicia");

    // Scope to the desktop table (the card list also renders a self badge).
    const table = container.querySelector(".users-table");
    const selfTags = table.querySelectorAll(".self-tag");
    expect(selfTags.length).toBe(1); // only the signed-in user's row
    // The whole "(You)" string lives in a single badge element, so the old
    // "(You" + ")" line-split cannot happen.
    expect(selfTags[0].textContent).toBe("(You)");
    // Badge sits inside the same name cell as the personnel name.
    expect(selfTags[0].closest(".user-name-text")).not.toBeNull();
    // Other rows never get the badge.
    expect(within(table).getByText("Jane Tan").closest("tr").querySelector(".self-tag")).toBeNull();
  });

  test("email and Face ID status remain visible for every row", async () => {
    const { container } = renderUsers();
    await screen.findAllByText("Jane Tan");
    const table = container.querySelector(".users-table");
    const t = within(table);
    expect(t.getByText("felicia@flowguard.dev")).toBeTruthy();
    expect(t.getByText("jane.tan@very-long-company-domain.example.com")).toBeTruthy();
    const faceIdBadges = [...table.querySelectorAll(".presence-tag")].map((el) => el.textContent.trim());
    expect(faceIdBadges).toEqual(["Enrolled", "Not Enrolled"]);
    // Joined dates stay visible too (.time-cell is table-only).
    expect(table.querySelectorAll(".time-cell").length).toBe(2);
  });

  test("table no longer forces a 1280px min-width (desktop fits without horizontal scroll)", () => {
    const css = fs.readFileSync(path.resolve(__dirname, "../../src/css/Users.css"), "utf8");
    expect(css).not.toMatch(/min-width:\s*1280px/);
    // Fixed layout + percentage columns keep the table within the viewport.
    expect(css).toMatch(/table-layout:\s*fixed/);
  });

  test("self row keeps suspend/delete restrictions (buttons disabled for yourself)", async () => {
    renderUsers();
    const selfRow = (await screen.findByText("Tan Xiu Li, Felicia")).closest("tr");
    const rowButtons = [...selfRow.querySelectorAll("button")];
    const suspendBtn = rowButtons.find((b) => /Suspend/.test(b.textContent));
    const deleteBtn = rowButtons.find((b) => /Delete/.test(b.textContent));
    expect(suspendBtn.disabled).toBe(true);
    expect(deleteBtn.disabled).toBe(true);
  });
});

describe("My Staff — Add Staff (Tenant)", () => {
  test("Tenant sees the + Add Staff button", () => {
    localStorage.setItem("userRole", "Tenant");
    renderStaff();
    expect(screen.getByRole("button", { name: /Add Staff/i })).toBeTruthy();
  });

  test("non-Tenant (FM) does not see the + Add Staff button", () => {
    localStorage.setItem("userRole", "FM");
    renderStaff();
    expect(screen.queryByRole("button", { name: /Add Staff/i })).toBeNull();
  });
});

// Frontend tests — Face ID enrolment badges and the FM re-enrol action on
// User Management, plus API-base consistency across Felicia's pages.
import React from "react";
import fs from "node:fs";
import path from "node:path";
import { render, screen, fireEvent, cleanup } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { describe, test, expect, vi, beforeEach, afterEach } from "vitest";

vi.mock("../../src/components/Sidebar", () => ({ default: () => <div data-testid="sidebar" /> }));

const mockNavigate = vi.fn();
vi.mock("react-router-dom", async (importOriginal) => {
  const actual = await importOriginal();
  return { ...actual, useNavigate: () => mockNavigate };
});

const mockAxios = vi.hoisted(() => ({ get: vi.fn(), post: vi.fn(), put: vi.fn(), delete: vi.fn() }));
vi.mock("axios", () => ({ default: mockAxios }));

import Users from "../../src/pages/Users";

const USERS = [
  { id: 25, name: "Enrolled Emma", email: "e@x.com", role: "Staff", isActive: true, isEnrolled: true, createdAt: "2026-01-01", locationStatus: "On-Site" },
  { id: 26, name: "Newbie Ng", email: "n@x.com", role: "Tenant", isActive: true, isEnrolled: false, createdAt: "2026-01-02", locationStatus: "Off-Site" },
];

beforeEach(() => {
  vi.clearAllMocks();
  localStorage.setItem("userRole", "FM");
  localStorage.setItem("userId", "1");
  mockAxios.get.mockResolvedValue({ data: USERS });
});

afterEach(() => {
  cleanup();
  localStorage.clear();
});

const renderUsers = async () => {
  render(<MemoryRouter><Users /></MemoryRouter>);
  await screen.findByText("Enrolled Emma");
};

describe("User Management — Face ID badge", () => {
  test("shows Enrolled / Not Enrolled per user", async () => {
    await renderUsers();
    const enrolled = document.querySelector('.presence-tag.on-site');
    const notEnrolled = document.querySelector('.presence-tag.off-site');
    expect(enrolled?.classList.contains('presence-tag')).toBe(true);
    expect(notEnrolled?.classList.contains('presence-tag')).toBe(true);
    expect(enrolled?.querySelector('svg')).toBeTruthy();
    expect(notEnrolled?.querySelector('svg')).toBeTruthy();
  });

  test("badge never renders biometric data", async () => {
    await renderUsers();
    expect(document.body.textContent).not.toMatch(/faceVector|embedding|\[\s*-?0\.\d+/);
  });
});

describe("User Management — Face ID enrolment removed from row actions", () => {
  test("no role sees an Enrol/Re-enrol Face ID row action (it lives in Settings / the enrolment flow)", async () => {
    await renderUsers();
    expect(screen.queryByRole("button", { name: /Re-enrol Face ID|Enrol Face ID|Face ID/ })).toBeNull();

    cleanup();
    localStorage.setItem("userRole", "Tenant");
    await renderUsers();
    expect(screen.queryByRole("button", { name: /Re-enrol Face ID|Enrol Face ID|Face ID/ })).toBeNull();
  });
});

describe("User Management — compact role badges", () => {
  test("role column shows a compact badge with a separate readable description", async () => {
    await renderUsers();
    // Compact badge text only — never a long combined label.
    expect(document.body.textContent).not.toMatch(/FM - FACILITIES MANAGER|Tenant - Unit Owner|Staff - Worker/i);
    const staffBadge = document.querySelector(".role-badge.role-staff");
    const tenantBadge = document.querySelector(".role-badge.role-tenant");
    expect(staffBadge.textContent).toBe("Staff");
    expect(tenantBadge.textContent).toBe("Tenant");
    // Accessible visible description, not colour-only.
    expect(screen.getByText("Worker")).toBeTruthy();
    expect(screen.getByText("Unit Owner")).toBeTruthy();
  });
});

describe("User Management — secure deletion flow", () => {
  test("self row has disabled Suspend and Delete controls", async () => {
    localStorage.setItem("userId", "25");
    await renderUsers();
    const row = screen.getByLabelText("Actions for Enrolled Emma");
    const buttons = [...row.querySelectorAll("button")];
    const suspendBtn = buttons.find((b) => /Suspend/.test(b.textContent));
    const deleteBtn = buttons.find((b) => /Delete/.test(b.textContent));
    expect(suspendBtn.disabled).toBe(true);
    expect(deleteBtn.disabled).toBe(true);
  });

  test("a 409 linked-Staff conflict from the server stays visible in the modal", async () => {
    await renderUsers();
    const row = screen.getByLabelText("Actions for Newbie Ng");
    fireEvent.click([...row.querySelectorAll("button")].find((b) => /Delete/.test(b.textContent)));
    fireEvent.change(screen.getByPlaceholderText("Newbie Ng"), { target: { value: "Newbie Ng" } });
    mockAxios.delete.mockRejectedValueOnce({ response: { status: 409, data: { message: "This tenant still has 2 linked Staff account(s)." } } });
    fireEvent.click(screen.getByRole("button", { name: /Permanently Delete/i }));
    expect((await screen.findByRole("alert")).textContent).toMatch(/linked Staff/i);
  });

  test("successful deletion refreshes the user list and shows the delete wording", async () => {
    await renderUsers();
    const row = screen.getByLabelText("Actions for Newbie Ng");
    fireEvent.click([...row.querySelectorAll("button")].find((b) => /Delete/.test(b.textContent)));
    expect(screen.getByText(/Permanently remove login access, Face ID enrolment and operational access/i)).toBeTruthy();

    fireEvent.change(screen.getByPlaceholderText("Newbie Ng"), { target: { value: "Newbie Ng" } });
    mockAxios.delete.mockResolvedValueOnce({ data: { message: "Removed" } });
    mockAxios.get.mockResolvedValueOnce({ data: [USERS[0]] });
    fireEvent.click(screen.getByRole("button", { name: /Permanently Delete/i }));

    await screen.findByText(/permanently removed from FlowGuard/i);
    expect(mockAxios.delete).toHaveBeenCalledWith(expect.stringContaining("/user/26"), expect.any(Object));
    // list re-fetched after the delete (initial load + refresh)
    expect(mockAxios.get.mock.calls.length).toBeGreaterThanOrEqual(2);
  });
});

describe("Deployment API-base consistency (static source check)", () => {
  const PAGES = [
    "Users.jsx", "StaffManagement.jsx", "Attendance.jsx", "SecurityReview.jsx",
    "UserLogs.jsx", "FaceEnrollment.jsx", "GateScanner.jsx", "VPatrol.jsx",
    "TenantLogistics.jsx", "DriverPass.jsx",
  ];
  const pagesDir = path.resolve(__dirname, "../../src/pages");

  test.each(PAGES)("%s imports the shared API_BASE_URL", (page) => {
    const source = fs.readFileSync(path.join(pagesDir, page), "utf8");
    expect(source).toMatch(/import \{ API_BASE_URL \} from ['"]\.\.\/constants\/api['"]/);
  });

  test.each(PAGES)("%s has no hardcoded relative API calls left", (page) => {
    const source = fs.readFileSync(path.join(pagesDir, page), "utf8");
    // Every axios/fetch call to the backend must go through the template base,
    // not a bare '/api/...' or '/user...' string literal.
    expect(source).not.toMatch(/axios\.(get|post|put|patch|delete)\(\s*['"]\/(api|user)/);
    expect(source).not.toMatch(/axios\.(get|post|put|patch|delete)\(\s*`\/(api|user)/);
    expect(source).not.toMatch(/fetch\(\s*[`'"]\/(api|user)/);
  });

  test("no page uses the retired VITE_API_URL variable", () => {
    for (const page of PAGES) {
      const source = fs.readFileSync(path.join(pagesDir, page), "utf8");
      expect(source).not.toMatch(/VITE_API_URL\b/);
    }
  });
});

